INSERT INTO cq_missions (slug,step_no,chapter_no,mission_type,title,body,question,options_json,correct_answer,feedback,xp_reward,lumen_reward,bonus_xp_correct,special_reward,available_from,available_until,repeatable,grants_streak,active,sort_order) VALUES ('c1e1-palavra',1,1,'palavra','Deus não está longe','Leia At 17,23-28. Paulo anuncia que em Deus vivemos, nos movemos e existimos. Escolha uma frase da passagem e releia-a lentamente.',NULL,NULL,NULL,NULL,10,3,0,NULL,'2026-09-10','2027-02-09',0,1,1,1) ON DUPLICATE KEY UPDATE step_no=VALUES(step_no),chapter_no=VALUES(chapter_no),mission_type=VALUES(mission_type),title=VALUES(title),body=VALUES(body),question=VALUES(question),options_json=VALUES(options_json),correct_answer=VALUES(correct_answer),feedback=VALUES(feedback),xp_reward=VALUES(xp_reward),lumen_reward=VALUES(lumen_reward),bonus_xp_correct=VALUES(bonus_xp_correct),special_reward=VALUES(special_reward),available_from=VALUES(available_from),available_until=VALUES(available_until),active=1,sort_order=VALUES(sort_order);
INSERT INTO cq_missions (slug,step_no,chapter_no,mission_type,title,body,question,options_json,correct_answer,feedback,xp_reward,lumen_reward,bonus_xp_correct,special_reward,available_from,available_until,repeatable,grants_streak,active,sort_order) VALUES ('c1e1-reflexao',1,1,'reflexao','O que meu coração procura?','Reserve dois minutos de silêncio. Pense no que você mais busca quando procura felicidade, sentido e pertencimento. A resposta pode permanecer privada.',NULL,NULL,NULL,NULL,15,4,0,NULL,'2026-09-10','2027-02-09',0,1,1,2) ON DUPLICATE KEY UPDATE step_no=VALUES(step_no),chapter_no=VALUES(chapter_no),mission_type=VALUES(mission_type),title=VALUES(title),body=VALUES(body),question=VALUES(question),options_json=VALUES(options_json),correct_answer=VALUES(correct_answer),feedback=VALUES(feedback),xp_reward=VALUES(xp_reward),lumen_reward=VALUES(lumen_reward),bonus_xp_correct=VALUES(bonus_xp_correct),special_reward=VALUES(special_reward),available_from=VALUES(available_from),available_until=VALUES(available_until),active=1,sort_order=VALUES(sort_order);
INSERT INTO cq_missions (slug,step_no,chapter_no,mission_type,title,body,question,options_json,correct_answer,feedback,xp_reward,lumen_reward,bonus_xp_correct,special_reward,available_from,available_until,repeatable,grants_streak,active,sort_order) VALUES ('c1e2-palavra',2,1,'palavra','Deus falou conosco','Leia Hb 1,1-2 e observe a passagem dos profetas para o Filho. Identifique quem toma a iniciativa da Revelação.',NULL,NULL,NULL,NULL,10,3,0,NULL,'2026-09-13','2027-02-09',0,1,1,3) ON DUPLICATE KEY UPDATE step_no=VALUES(step_no),chapter_no=VALUES(chapter_no),mission_type=VALUES(mission_type),title=VALUES(title),body=VALUES(body),question=VALUES(question),options_json=VALUES(options_json),correct_answer=VALUES(correct_answer),feedback=VALUES(feedback),xp_reward=VALUES(xp_reward),lumen_reward=VALUES(lumen_reward),bonus_xp_correct=VALUES(bonus_xp_correct),special_reward=VALUES(special_reward),available_from=VALUES(available_from),available_until=VALUES(available_until),active=1,sort_order=VALUES(sort_order);
INSERT INTO cq_missions (slug,step_no,chapter_no,mission_type,title,body,question,options_json,correct_answer,feedback,xp_reward,lumen_reward,bonus_xp_correct,special_reward,available_from,available_until,repeatable,grants_streak,active,sort_order) VALUES ('c1e2-quiz',2,1,'quiz','Revelação é iniciativa de quem?','Marque a alternativa que melhor resume a fé cristã sobre a Revelação.','A Revelação cristã começa principalmente com...','["A - o esforço humano de descobrir sozinho Deus","B - Deus que se comunica e chama o ser humano à comunhão","C - costumes culturais sem relação com Deus"]','B','Na fé cristã, Deus toma a iniciativa de se revelar e convida a uma resposta livre.',10,2,5,NULL,'2026-09-13','2027-02-09',0,1,1,4) ON DUPLICATE KEY UPDATE step_no=VALUES(step_no),chapter_no=VALUES(chapter_no),mission_type=VALUES(mission_type),title=VALUES(title),body=VALUES(body),question=VALUES(question),options_json=VALUES(options_json),correct_answer=VALUES(correct_answer),feedback=VALUES(feedback),xp_reward=VALUES(xp_reward),lumen_reward=VALUES(lumen_reward),bonus_xp_correct=VALUES(bonus_xp_correct),special_reward=VALUES(special_reward),available_from=VALUES(available_from),available_until=VALUES(available_until),active=1,sort_order=VALUES(sort_order);
